row(17, 1, 'MATERIAL', f'YOU SHALL NOT SACRIFICE TO THE LORD YOUR GOD AN OX OR A SHEEP WITH A BLEMISH, ANY EVIL THING, FOR IT IS AN ABOMINATION TO THE LORD YOUR GOD. {HP(17, 1, (("שור", "ושה", "אשר", "יהיה", "בו", "מום"), "an ox or a sheep which has a blemish — 15:21 its closest kin"), (("כל", "דבר", "רע"), "any evil thing — one seat"))} {AP(17, 1, (("ארי", "מרחק", "קדם", "יי"), "FOR IT IS DISTANCED BEFORE THE LORD — abomination rendered as distance, the book\'s eleven seats"))} THE BLEMISH: 147:1-7\'s nine classes; 99:2 and 261:2 the word\'s twins. Fresh.')
row(17, 2, 'MATERIAL', f'WHEN THERE IS FOUND IN YOUR MIDST, IN ONE OF YOUR GATES WHICH THE LORD YOUR GOD GIVES YOU, A MAN OR A WOMAN WHO DOES EVIL IN THE EYES OF THE LORD YOUR GOD, TRANSGRESSING HIS COVENANT. {HP(17, 2, (("כי", "ימצא", "בקרבך", "באחד", "שעריך"), "when there is found in your midst in one of your gates — the parser reads [1]"), (("לעבר", "בריתו"), "to transgress His covenant"))} {AP(17, 2, (("ארי", "ישתכח", "בינך", "בחדא", "מקרויך"), "when there is found among you in one of your CITIES"), (("למעבר", "על", "קימיה"), "to transgress His covenant"))} FOUND: 148:1\'s witnesses; 148:2\'s gate. Fresh.')
row(17, 3, 'MATERIAL', f'AND GOES AND SERVES OTHER GODS AND BOWS TO THEM, TO THE SUN OR THE MOON OR ALL THE HOST OF HEAVEN, WHICH I HAVE NOT COMMANDED. {HP(17, 3, (("וילך", "ויעבד", "אלהים", "אחרים", "וישתחו"), "and goes and serves other gods and bows — three narrative-form verbs inside the case"), (("אשר", "לא", "צויתי"), "which I have not commanded — the LORD\'s own first person; Jeremiah 19:5 and 7:31 its twins"))} {AP(17, 3, (("ופלח", "לטעות", "עממיא"), "AND SERVES THE IDOLS OF THE NATIONS — for other gods"), (("די", "לא", "פקדית"), "which I have not commanded"))} THE THREE ACTS: 148:6; 148:8-10 the host and the three words. Fresh.')
row(17, 4, 'MATERIAL', f'AND IT IS TOLD YOU AND YOU HEAR AND INQUIRE WELL, AND BEHOLD IT IS TRUE, THE THING IS CERTAIN, THIS ABOMINATION WAS DONE IN ISRAEL. {HP(17, 4, (("והגד", "לך", "ושמעת", "ודרשת", "היטב"), "and it is told you and you hear and inquire well — nine tokens in order with 13:15"), (("והנה", "אמת", "נכון", "הדבר"), "and behold it is true, the thing is certain"))} {AP(17, 4, (("ותתבע", "יאות"), "and you inquire well"), (("והא", "קשטא", "כון", "פתגמא"), "and behold the thing is true and certain"))} THE INQUIRY: 149:1-2\'s seven investigations and the probes. Fresh.')
row(17, 5, 'MATERIAL', f'AND YOU SHALL BRING OUT THAT MAN OR THAT WOMAN WHO DID THIS EVIL THING TO YOUR GATES, THE MAN OR THE WOMAN, AND STONE THEM WITH STONES THAT THEY DIE. {HP(17, 5, (("והוצאת", "את", "האיש", "ההוא"), "and you shall bring out that man"), (("אל", "שעריך"), "to your gates — the gate where found (148:2, 149:4)"), (("וסקלתם", "באבנים", "ומתו"), "and stone them with stones that they die"))} {AP(17, 5, (("לתרע", "בית", "דינך"), "TO THE GATE OF YOUR COURT — the gate a court, one seat"), (("ותרגמנון", "באבניא", "וימותון"), "and you shall stone them with stones and they die"))} THE STONING: 149:5-7. Fresh.')
row(17, 6, 'MATERIAL', f'BY THE MOUTH OF TWO WITNESSES OR THREE WITNESSES SHALL THE DEAD DIE; HE SHALL NOT DIE BY THE MOUTH OF ONE WITNESS. {HP(17, 6, (("על", "פי", "שנים", "עדים", "או", "שלשה", "עדים"), "by the mouth of two witnesses or three witnesses — one seat; the parser reads [2, 3, 1]"), (("לא", "יומת", "על", "פי", "עד", "אחד"), "he shall not die by the mouth of one witness"))} {AP(17, 6, (("על", "מימר", "תרין", "סהדין"), "BY THE MEMRA OF TWO WITNESSES — the mouth a word"), (("יתקטל", "דחיב", "קטול"), "the one liable to death shall be killed — for the dead"))} THE WITNESSES: 150:1-3; 190:3 the men. Fresh.')
row(17, 7, 'MATERIAL', f'THE HAND OF THE WITNESSES SHALL BE ON HIM FIRST TO PUT HIM TO DEATH, AND THE HAND OF ALL THE PEOPLE AFTERWARD; AND YOU SHALL PURGE THE EVIL FROM YOUR MIDST. {HP(17, 7, (("יד", "העדים", "תהיה", "בו", "בראשנה"), "the hand of the witnesses shall be on him first — 13:10 the brother\'s"), (("ובערת", "הרע", "מקרבך"), "and you shall purge the evil from your midst — the second seat of nine"))} {AP(17, 7, (("ידא", "דסהדיא", "תהי", "ביה", "בקדמיתא"), "the hand of the witnesses shall be on him first"), (("ותפלי", "עבד", "דביש", "מבינך"), "AND YOU SHALL PURGE THE DOER OF EVIL FROM AMONG YOU — a person, at every purge seat"))} THE HAND: 151:1-3; 306:9 REREAD. Fresh.')
row(17, 8, 'MATERIAL', f'WHEN A MATTER IS TOO HARD FOR YOU IN JUDGMENT, BETWEEN BLOOD AND BLOOD, PLEA AND PLEA, STROKE AND STROKE, MATTERS OF DISPUTE IN YOUR GATES, YOU SHALL RISE AND GO UP TO THE PLACE WHICH THE LORD YOUR GOD WILL CHOOSE. {HP(17, 8, (("כי", "יפלא", "ממך", "דבר", "למשפט"), "when a matter is too hard for you in judgment — nothing in order with Exodus 18:22"), (("בין", "דם", "לדם"), "between blood and blood — 2 Chronicles 19:10 its one twin"), (("וקמת", "ועלית", "אל", "המקום"), "and you shall rise and go up to the place — 37:16, 317:2, 352:9 cite it"))} {AP(17, 8, (("ארי", "יתכסי", "מנך", "פתגמא"), "when a matter is hidden from you"), (("מכתש", "סגירו", "למכתש", "סגירו"), "the plague of confinement and the plague of confinement — the stroke a leprosy"), (("דינא", "בקרויך"), "judgment in your cities"))} THE HARD CASE: 152:1-15. Fresh.')
row(17, 9, 'MATERIAL', f'AND YOU SHALL COME TO THE PRIESTS THE LEVITES AND TO THE JUDGE WHO SHALL BE IN THOSE DAYS, AND INQUIRE, AND THEY SHALL TELL YOU THE WORD OF JUDGMENT. {HP(17, 9, (("אל", "הכהנים", "הלוים", "ואל", "השפט"), "to the priests the Levites and to the judge — the book\'s three seats of the pair"), (("אשר", "יהיה", "בימים", "ההם"), "who shall be in those days — 26:3 its kin"))} {AP(17, 9, (("לות", "כהניא", "לואי", "ולות", "דינא"), "to the priests the Levites and to the judge"), (("ויחוון", "לך", "ית", "פתגמא", "דדינא"), "and they shall tell you the word of judgment"))} THE COURT: 153:1-5. Fresh.')
row(17, 10, 'MATERIAL', f'AND YOU SHALL DO ACCORDING TO THE WORD THEY TELL YOU FROM THAT PLACE WHICH THE LORD WILL CHOOSE, AND KEEP TO DO ALL THEY TEACH YOU. {HP(17, 10, (("ועשית", "על", "פי", "הדבר"), "and you shall do according to the word"), (("מן", "המקום", "ההוא", "אשר", "יבחר", "יהוה"), "from that place which the LORD will choose — 152:14\'s seat"))} {AP(17, 10, (("ותעבד", "על", "מימר", "פתגמא"), "AND YOU SHALL DO BY THE MEMRA OF THE WORD"), (("ככל", "די", "ילפנך"), "according to all they teach you"))} THE RULING: 154:1. Fresh.')
