row(17, 12, 'MATERIAL', f'AND THE MAN WHO ACTS PRESUMPTUOUSLY, NOT HEARKENING TO THE PRIEST WHO STANDS TO MINISTER THERE BEFORE THE LORD YOUR GOD OR TO THE JUDGE, THAT MAN SHALL DIE; AND YOU SHALL PURGE THE EVIL FROM ISRAEL. {HP(17, 12, (("והאיש", "אשר", "יעשה", "בזדון"), "and the man who acts presumptuously — the noun\'s two Torah seats"), (("הכהן", "העמד", "לשרת", "שם"), "the priest who stands to minister there"), (("ובערת", "הרע", "מישראל"), "and you shall purge the evil from Israel — the second form"))} {AP(17, 12, (("וגבר", "די", "יעבד", "ברשע"), "and the man who acts IN WICKEDNESS"), (("ותפלי", "עבד", "דביש", "מישראל"), "and you shall purge the doer of evil from Israel"))} THE REBEL: 155:1-9. Fresh.')
row(17, 13, 'MATERIAL', f'AND ALL THE PEOPLE SHALL HEAR AND FEAR, AND NOT ACT PRESUMPTUOUSLY AGAIN. {HP(17, 13, (("וכל", "העם", "ישמעו", "ויראו"), "and all the people shall hear and fear — three seats"), (("ולא", "יזידון", "עוד"), "and not act presumptuously again"))} {AP(17, 13, (("ישמעון", "וידחלון"), "shall hear and fear"), (("ולא", "ירשיעון", "עוד"), "and not act wickedly again"))} THE DETERRENT: the compile\'s "hear and fear" effect on the population. Fresh.')
row(17, 14, 'MATERIAL', f'WHEN YOU COME INTO THE LAND WHICH THE LORD YOUR GOD GIVES YOU AND POSSESS IT AND DWELL IN IT, AND SAY: I WILL SET A KING OVER ME LIKE ALL THE NATIONS AROUND ME. {HP(17, 14, (("כי", "תבא", "אל", "הארץ"), "when you come into the land — ten tokens in order with 26:1"), (("ואמרת", "אשימה", "עלי", "מלך"), "and you say, I will set a king over me — the people\'s first person"), (("ככל", "הגוים", "אשר", "סביבתי"), "like all the nations around me — one seat"))} {AP(17, 14, (("ותימר", "אמני", "עלי", "מלכא"), "and you say, I will appoint over me a king"), (("ככל", "עממיא"), "like all the nations"))} THE REQUEST: 156:1-6. Fresh.')
