row(17, 16, 'MATERIAL', f'ONLY HE SHALL NOT MULTIPLY HORSES FOR HIMSELF, NOR RETURN THE PEOPLE TO EGYPT TO MULTIPLY HORSE, FOR THE LORD SAID TO YOU: YOU SHALL NOT RETURN THAT WAY AGAIN. {HP(17, 16, (("רק", "לא", "ירבה", "לו", "סוסים"), "only he shall not multiply horses for himself"), (("ולא", "ישיב", "את", "העם", "מצרימה"), "nor return the people to Egypt"), (("ויהוה", "אמר", "לכם"), "and the LORD said to you (pl.) — the chapter\'s one plural, Exodus 14:13\'s word"))} {AP(17, 16, (("לא", "יסגי", "ליה", "סוסון"), "he shall not multiply horses for himself"), (("לא", "תוספון", "למתוב", "בארח", "הדא", "עוד"), "you shall not return that way again"))} THE HORSES: 158:1-4. Fresh.')
